async function sendVerificationEmail(email,code,type="email_verification"){const endpoint=process.env.GMAIL_APPS_SCRIPT_URL,secret=process.env.BEP_MAIL_SECRET;if(!endpoint||!secret)throw Error("EMAIL_SERVICE_NOT_CONFIGURED");const response=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({secret,email,code,type,resetUrl:type==="password_reset"?code:undefined,subject:type==="password_reset"?"Réinitialisation du mot de passe BEP":"Vérification de ton adresse e-mail BEP"})});const result=await response.json();if(!response.ok||!result.ok)throw Error("EMAIL_SEND_FAILED")}
app.post("/api/auth/forgot-password",async(req,res)=>{res.setHeader("Cache-Control","no-store");try{const email=String(req.body?.email||"").trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return res.status(200).json({ok:true,message:"Si un compte correspond à cette adresse, un lien de réinitialisation sera envoyé."});const user=await pool.query("SELECT id FROM bep_users WHERE LOWER(email)=LOWER($1) ORDER BY created_at DESC",[email]);if(user.rowCount===1){const token=crypto.randomBytes(32).toString("hex"),tokenHash=crypto.createHash("sha256").update(token).digest("hex");await pool.query("INSERT INTO bep_password_reset_tokens(token_hash,user_id,expires_at) VALUES($1,$2,NOW()+INTERVAL '30 minutes') ON CONFLICT(user_id) DO UPDATE SET token_hash=EXCLUDED.token_hash,expires_at=EXCLUDED.expires_at,created_at=NOW()",[tokenHash,user.rows[0].id]);const resetUrl=FRONTEND_ORIGIN+"/?reset="+encodeURIComponent(token);try{await sendVerificationEmail(email,resetUrl,"password_reset")}catch(mailError){console.error("Password reset email failed",mailError.message);await pool.query("DELETE FROM bep_password_reset_tokens WHERE token_hash=$1",[tokenHash])}}return res.status(200).json({ok:true,message:"Si un compte correspond à cette adresse, un lien de réinitialisation sera envoyé."})}catch(e){console.error("Password reset request failed",e.message);return res.status(200).json({ok:true,message:"Si un compte correspond à cette adresse, un lien de réinitialisation sera envoyé."})}});
app.post("/api/auth/reset-password",async(req,res)=>{res.setHeader("Cache-Control","no-store");const token=String(req.body?.token||""),password=String(req.body?.password||"");if(!/^[a-f0-9]{64}$/.test(token)||password.length<10||password.length>128)return res.status(400).json({error:"RESET_INVALID",message:"Lien invalide ou mot de passe non conforme (10 caractères minimum)."});const tokenHash=crypto.createHash("sha256").update(token).digest("hex");const client=await pool.connect();try{await client.query("BEGIN");const found=await client.query("SELECT user_id FROM bep_password_reset_tokens WHERE token_hash=$1 AND expires_at>NOW() FOR UPDATE",[tokenHash]);if(!found.rowCount){await client.query("ROLLBACK");return res.status(400).json({error:"RESET_EXPIRED",message:"Ce lien est invalide ou expiré. Demande un nouveau lien."})}const userId=found.rows[0].user_id,hash=await bcrypt.hash(password,12);await client.query("UPDATE bep_users SET password_hash=$1,email_verified=TRUE,updated_at=NOW() WHERE id=$2",[hash,userId]);await client.query("DELETE FROM bep_password_reset_tokens WHERE user_id=$1",[userId]);await client.query("DELETE FROM user_sessions WHERE sess->'user'->>'id'=$1",[userId]);await client.query("COMMIT");return res.json({ok:true,message:"Ton mot de passe a été réinitialisé. Tu peux maintenant te connecter."})}catch(e){await client.query("ROLLBACK").catch(()=>{});console.error("Password reset confirmation failed",e.message);return res.status(500).json({error:"RESET_FAILED",message:"La réinitialisation a échoué. Réessaie."})}finally{client.release()}});
app.post("/api/auth/register",async(req,res)=>{try{const email=String(req.body?.email||"").trim().toLowerCase(),password=String(req.body?.password||""),name=String(req.body?.name||"").trim().slice(0,80);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<10||password.length>128)return res.status(400).json({error:"EMAIL_OR_PASSWORD_INVALID",message:"Adresse e-mail invalide ou mot de passe inférieur à 10 caractères."});const exists=await pool.query("SELECT id FROM bep_users WHERE LOWER(email)=LOWER($1)",[email]);if(exists.rowCount)return res.status(409).json({error:"ACCOUNT_EXISTS",message:"Un compte existe déjà avec cette adresse."});const id="email:"+crypto.randomUUID(),hash=await bcrypt.hash(password,12);await pool.query("INSERT INTO bep_users(id,email,display_name,password_hash,email_verified) VALUES($1,$2,$3,$4,FALSE)",[id,email,name,hash]);await pool.query("INSERT INTO bep_user_data(user_id) VALUES($1)",[id]);const code=String(crypto.randomInt(0,1000000)).padStart(6,"0"),codeHash=crypto.createHash("sha256").update(code).digest("hex");await pool.query("INSERT INTO bep_email_verifications(email,user_id,code_hash,expires_at) VALUES($1,$2,$3,NOW()+INTERVAL '10 minutes') ON CONFLICT(email) DO UPDATE SET user_id=EXCLUDED.user_id,code_hash=EXCLUDED.code_hash,expires_at=EXCLUDED.expires_at,attempts=0,created_at=NOW()",[email,id,codeHash]);try{await sendVerificationEmail(email,code)}catch(mailError){console.error("Verification email failed",mailError.message);return res.status(503).json({error:"EMAIL_SEND_FAILED",message:"Compte préparé, mais l'e-mail n'a pas pu être envoyé. Réessaie l'envoi du code."})}res.status(201).json({ok:true,verificationRequired:true,email})}catch(e){console.error("Register error",e.message);res.status(500).json({error:"REGISTER_FAILED"})}});
app.post("/api/auth/verify-email",async(req,res)=>{try{const email=String(req.body?.email||"").trim().toLowerCase(),code=String(req.body?.code||"").trim();if(!/^\d{6}$/.test(code))return res.status(400).json({error:"INVALID_CODE",message:"Saisis le code à 6 chiffres."});const v=await pool.query("SELECT v.*,u.email_verified FROM bep_email_verifications v JOIN bep_users u ON u.id=v.user_id WHERE v.email=$1 AND v.expires_at>NOW()",[email]);if(!v.rowCount)return res.status(400).json({error:"CODE_EXPIRED",message:"Code expiré. Demande un nouveau code."});if(v.rows[0].attempts>=5)return res.status(429).json({error:"TOO_MANY_ATTEMPTS",message:"Trop de tentatives. Demande un nouveau code."});const hash=crypto.createHash("sha256").update(code).digest("hex");if(hash!==v.rows[0].code_hash){await pool.query("UPDATE bep_email_verifications SET attempts=attempts+1 WHERE email=$1",[email]);return res.status(400).json({error:"INVALID_CODE",message:"Code incorrect."})}const userId=v.rows[0].user_id;await pool.query("UPDATE bep_users SET email_verified=TRUE,updated_at=NOW() WHERE id=$1",[userId]);await pool.query("DELETE FROM bep_email_verifications WHERE email=$1",[email]);const u=await pool.query("SELECT id,email,display_name FROM bep_users WHERE id=$1",[userId]);req.session.regenerate(err=>{if(err)return res.status(500).json({error:"SESSION_ERROR"});req.session.user={id:u.rows[0].id,email:u.rows[0].email,name:u.rows[0].display_name||"",picture:""};req.session.save(e=>e?res.status(500).json({error:"SESSION_ERROR"}):res.json({ok:true,user:req.session.user}))})}catch(e){console.error("Email verification error",e.message);res.status(500).json({error:"VERIFICATION_FAILED"})}});
app.post("/api/auth/resend-verification",async(req,res)=>{try{const email=String(req.body?.email||"").trim().toLowerCase(),u=await pool.query("SELECT id,email_verified FROM bep_users WHERE email=$1 AND id LIKE 'email:%'",[email]);if(!u.rowCount||u.rows[0].email_verified)return res.json({ok:true});const code=String(crypto.randomInt(0,1000000)).padStart(6,"0"),codeHash=crypto.createHash("sha256").update(code).digest("hex");await pool.query("INSERT INTO bep_email_verifications(email,user_id,code_hash,expires_at) VALUES($1,$2,$3,NOW()+INTERVAL '10 minutes') ON CONFLICT(email) DO UPDATE SET code_hash=EXCLUDED.code_hash,expires_at=EXCLUDED.expires_at,attempts=0,created_at=NOW()",[email,u.rows[0].id,codeHash]);await sendVerificationEmail(email,code);res.json({ok:true})}catch(e){console.error("Resend verification failed",e.message);res.status(503).json({error:"EMAIL_SEND_FAILED",message:"Impossible d'envoyer le code pour le moment."})}});
app.post("/api/auth/login",async(req,res)=>{try{const email=String(req.body?.email||"").trim().toLowerCase(),password=String(req.body?.password||"");const r=await pool.query("SELECT id,email,display_name,password_hash,email_verified FROM bep_users WHERE LOWER(email)=LOWER($1) ORDER BY created_at DESC",[email]);const matches=[];for(const candidate of r.rows){if(candidate.password_hash&&await bcrypt.compare(password,candidate.password_hash))matches.push(candidate)}if(!matches.length)return res.status(401).json({error:"LOGIN_INVALID",message:"Adresse e-mail ou mot de passe incorrect."});if(matches.length>1)return res.status(409).json({error:"ACCOUNT_AMBIGUOUS",message:"Plusieurs comptes utilisent cette adresse. La connexion est temporairement bloquée pour protéger tes données. Contacte le support BEP."});const u=matches[0];if(u.email_verified===false)return res.status(403).json({error:"EMAIL_NOT_VERIFIED",message:"Confirme ton adresse e-mail avant de te connecter."});req.session.regenerate(err=>{if(err)return res.status(500).json({error:"SESSION_ERROR"});req.session.user={id:u.id,email:u.email,name:u.display_name||"",picture:""};req.session.save(e=>e?res.status(500).json({error:"SESSION_ERROR"}):res.json({ok:true,user:req.session.user}))})}catch(e){console.error("Login error",e.message);res.status(500).json({error:"LOGIN_FAILED"})}});
function hashOAuthState(state){return crypto.createHash("sha256").update(state).digest("hex")}
app.get("/api/auth/google",async(req,res)=>{try{if(!configured())return res.status(503).send("Google OAuth n'est pas encore configuré.");const state=crypto.randomBytes(32).toString("hex"),tokenHash=hashOAuthState(state);await pool.query("DELETE FROM bep_oauth_state_tokens WHERE expires_at<NOW()");await pool.query("INSERT INTO bep_oauth_state_tokens(token_hash,expires_at,flow,user_id) VALUES($1,NOW()+INTERVAL '10 minutes','login',NULL)",[tokenHash]);const p=new URLSearchParams({client_id:process.env.GOOGLE_CLIENT_ID,redirect_uri:process.env.GOOGLE_REDIRECT_URI,response_type:"code",scope:"openid email profile",state,prompt:"select_account"});res.redirect("https://accounts.google.com/o/oauth2/v2/auth?"+p)}catch(e){console.error("OAuth start failed",e.message);res.status(500).send("Impossible de démarrer la connexion Google. Réessaie.")}});
app.post("/api/auth/google/link/start",auth,async(req,res)=>{try{const account=await pool.query("SELECT id,email,password_hash FROM bep_users WHERE id=$1",[req.session.user.id]);if(!account.rowCount)return res.status(404).json({error:"ACCOUNT_NOT_FOUND"});const u=account.rows[0];if(u.password_hash){const password=String(req.body?.password||"");if(!password||!await bcrypt.compare(password,u.password_hash))return res.status(401).json({error:"REAUTH_REQUIRED",message:"Confirme le mot de passe de ton compte BEP avant de continuer."})}const state=crypto.randomBytes(32).toString("hex"),tokenHash=hashOAuthState(state);await pool.query("DELETE FROM bep_oauth_state_tokens WHERE expires_at<NOW()");await pool.query("INSERT INTO bep_oauth_state_tokens(token_hash,expires_at,flow,user_id) VALUES($1,NOW()+INTERVAL '10 minutes','link',$2)",[tokenHash,u.id]);const p=new URLSearchParams({client_id:process.env.GOOGLE_CLIENT_ID,redirect_uri:process.env.GOOGLE_REDIRECT_URI,response_type:"code",scope:"openid email profile",state,prompt:"select_account"});res.json({url:"https://accounts.google.com/o/oauth2/v2/auth?"+p})}catch(e){console.error("Google link start failed",e.message);res.status(500).json({error:"LINK_START_FAILED"})}});
app.get("/api/auth/google/callback",async(req,res)=>{let stage="callback";try{if(!configured())return res.status(503).send("Google OAuth n'est pas configuré.");if(!req.query.code)return res.status(400).send("Google n'a pas renvoyé de code d'autorisation. Recommence la connexion.");if(typeof req.query.state!=="string"||!/^[a-f0-9]{64}$/.test(req.query.state))return res.status(400).send("La demande de connexion Google est invalide. Recommence la connexion.");stage="state-validation";const tokenHash=hashOAuthState(req.query.state);const stateResult=await pool.query("DELETE FROM bep_oauth_state_tokens WHERE token_hash=$1 AND expires_at>NOW() RETURNING flow,user_id",[tokenHash]);if(stateResult.rowCount!==1)return res.status(400).send("La demande de connexion Google a expiré ou est invalide. Recommence la connexion.");const oauthState=stateResult.rows[0];stage="token-exchange";const t=await fetch("https://oauth2.googleapis.com/token",{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body:new URLSearchParams({code:req.query.code,client_id:process.env.GOOGLE_CLIENT_ID,client_secret:process.env.GOOGLE_CLIENT_SECRET,redirect_uri:process.env.GOOGLE_REDIRECT_URI,grant_type:"authorization_code"})});const tokens=await t.json();if(!t.ok||!tokens.access_token){console.error("Google token exchange rejected",JSON.stringify({httpStatus:t.status,error:tokens.error||"unknown"}));if(tokens.error==="invalid_client")return res.redirect(FRONTEND_ORIGIN+"/?login=google_config_error");throw Error("TOKEN_EXCHANGE_FAILED")}stage="profile";const g=await fetch("https://openidconnect.googleapis.com/v1/userinfo",{headers:{authorization:"Bearer "+tokens.access_token}}),u=await g.json();if(!g.ok||!u.sub||!u.email||!u.email_verified)throw Error("GOOGLE_PROFILE_FAILED");const email=String(u.email).trim().toLowerCase();
if(oauthState.flow==="link"){stage="link-verification";if(!oauthState.user_id||!req.session?.user||req.session.user.id!==oauthState.user_id)return res.redirect(FRONTEND_ORIGIN+"/?login=link_session_required");const account=await pool.query("SELECT id,email,display_name,google_sub FROM bep_users WHERE id=$1",[oauthState.user_id]);if(!account.rowCount)return res.redirect(FRONTEND_ORIGIN+"/?login=link_account_missing");const current=account.rows[0];if(String(current.email).toLowerCase()!==email)return res.redirect(FRONTEND_ORIGIN+"/?login=link_email_mismatch");if(current.google_sub&&current.google_sub!==u.sub)return res.redirect(FRONTEND_ORIGIN+"/?login=google_already_linked");const conflict=await pool.query("SELECT id FROM bep_users WHERE google_sub=$1 AND id<>$2",[u.sub,current.id]);if(conflict.rowCount)return res.redirect(FRONTEND_ORIGIN+"/?login=google_already_linked");await pool.query("UPDATE bep_users SET google_sub=$1,avatar_url=COALESCE(NULLIF($2,''),avatar_url),updated_at=NOW() WHERE id=$3 AND (google_sub IS NULL OR google_sub=$1)",[u.sub,u.picture||"",current.id]);req.session.user={...req.session.user,id:current.id,email:current.email,name:current.display_name||req.session.user.name||"",picture:u.picture||""};return req.session.save(err=>err?res.redirect(FRONTEND_ORIGIN+"/?login=link_session_error"):res.redirect(FRONTEND_ORIGIN+"/?login=google_linked"))}
stage="database-user";let found=await pool.query("SELECT id,email,display_name,avatar_url FROM bep_users WHERE google_sub=$1",[u.sub]);if(!found.rowCount){const byEmail=await pool.query("SELECT id FROM bep_users WHERE LOWER(email)=LOWER($1)",[email]);if(byEmail.rowCount)return res.redirect(FRONTEND_ORIGIN+"/?login=link_required");await pool.query("INSERT INTO bep_users(id,email,display_name,avatar_url,google_sub) VALUES($1,$2,$3,$4,$1)",[u.sub,email,u.name||"",u.picture||""]);await pool.query("INSERT INTO bep_user_data(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING",[u.sub]);found=await pool.query("SELECT id,email,display_name,avatar_url FROM bep_users WHERE google_sub=$1",[u.sub])}const user=found.rows[0];if(String(user.email).toLowerCase()!==email)return res.redirect(FRONTEND_ORIGIN+"/?login=google_email_changed");stage="session-save";req.session.regenerate(err=>{if(err)return res.status(500).send("La session n'a pas pu être créée. Réessaie.");req.session.user={id:user.id,email:user.email,name:user.display_name||u.name||"",picture:user.avatar_url||u.picture||""};req.session.save(e=>e?res.status(500).send("La session n'a pas pu être enregistrée. Réessaie."):res.redirect(FRONTEND_ORIGIN+"/?login=success"))})}catch(e){console.error("OAuth error",JSON.stringify({stage,message:e.message}));res.redirect(FRONTEND_ORIGIN+"/?login=error")}});
app.post("/api/auth/logout",(req,res)=>{const cookieOptions={path:"/",httpOnly:true,secure:true,sameSite:"none"};if(!req.session){res.clearCookie("connect.sid",cookieOptions);return res.json({ok:true})}req.session.destroy(err=>{res.clearCookie("connect.sid",cookieOptions);if(err){console.error("Logout session destroy failed",err.message);return res.status(500).json({error:"LOGOUT_FAILED"})}res.setHeader("Cache-Control","no-store");res.json({ok:true})})});
app.get("/api/me",auth,async(req,res)=>{const r=await pool.query("SELECT id,email,display_name,first_name,last_name,phone_number,avatar_url FROM bep_users WHERE id=$1",[req.session.user.id]);if(!r.rowCount)return res.status(404).json({error:"ACCOUNT_NOT_FOUND"});const u=r.rows[0];res.setHeader("Cache-Control","no-store");res.json({user:{id:u.id,email:u.email,name:u.display_name||"",firstName:u.first_name||"",lastName:u.last_name||"",phone:u.phone_number||"",picture:u.avatar_url||""}})});
app.put("/api/profile",auth,async(req,res)=>{const firstName=String(req.body?.firstName||"").trim().slice(0,80),lastName=String(req.body?.lastName||"").trim().slice(0,80),phone=String(req.body?.phone||"").trim().slice(0,30);if(!firstName||!lastName)return res.status(400).json({error:"PROFILE_REQUIRED",message:"Le prénom et le nom sont obligatoires."});if(phone&&!/^[+0-9(). /-]{6,30}$/.test(phone))return res.status(400).json({error:"PHONE_INVALID",message:"Le numéro de téléphone n'est pas valide."});const displayName=(firstName+" "+lastName).trim();await pool.query("UPDATE bep_users SET first_name=$2,last_name=$3,phone_number=$4,display_name=$5,updated_at=NOW() WHERE id=$1",[req.session.user.id,firstName,lastName,phone||null,displayName]);req.session.user.name=displayName;await new Promise((resolve,reject)=>req.session.save(e=>e?reject(e):resolve()));res.json({ok:true,profile:{firstName,lastName,phone}})});
app.delete("/api/account",auth,async(req,res)=>{const userId=req.session.user.id;const client=await pool.connect();try{await client.query("BEGIN");await client.query("DELETE FROM user_sessions WHERE sess->'user'->>'id'=$1",[userId]);await client.query("DELETE FROM bep_oauth_state_tokens WHERE user_id=$1",[userId]);const deleted=await client.query("DELETE FROM bep_users WHERE id=$1 RETURNING id",[userId]);if(!deleted.rowCount)throw Error("ACCOUNT_NOT_FOUND");await client.query("COMMIT")}catch(e){await client.query("ROLLBACK");console.error("Account deletion failed",e.message);return res.status(e.message==="ACCOUNT_NOT_FOUND"?404:500).json({error:"ACCOUNT_DELETE_FAILED",message:"La suppression du compte n'a pas pu être confirmée."})}finally{client.release()}const cookieOptions={path:"/",httpOnly:true,secure:true,sameSite:"none"};if(req.session)req.session.destroy(err=>{res.clearCookie("connect.sid",cookieOptions);if(err)return res.status(500).json({error:"SESSION_CLEANUP_FAILED",message:"Compte supprimé, mais la session doit être fermée."});res.setHeader("Cache-Control","no-store");res.json({ok:true})});else{res.clearCookie("connect.sid",cookieOptions);res.json({ok:true})}});

function aiEncryptionKey(){const raw=process.env.BEP_AI_ENCRYPTION_KEY||"";if(!/^[a-f0-9]{64}$/i.test(raw))throw Error("AI_ENCRYPTION_NOT_CONFIGURED");return Buffer.from(raw,"hex")}
function encryptAiKey(value){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv("aes-256-gcm",aiEncryptionKey(),iv),encrypted=Buffer.concat([cipher.update(value,"utf8"),cipher.final()]);return{encrypted_key:encrypted.toString("base64"),key_iv:iv.toString("base64"),key_tag:cipher.getAuthTag().toString("base64")}}
function decryptAiKey(row){const d=crypto.createDecipheriv("aes-256-gcm",aiEncryptionKey(),Buffer.from(row.key_iv,"base64"));d.setAuthTag(Buffer.from(row.key_tag,"base64"));return Buffer.concat([d.update(Buffer.from(row.encrypted_key,"base64")),d.final()]).toString("utf8")}
const aiProviders={openai:{url:"https://api.openai.com/v1/chat/completions",kind:"openai"},anthropic:{url:"https://api.anthropic.com/v1/messages",kind:"anthropic"},gemini:{url:"https://generativelanguage.googleapis.com",kind:"gemini"},mistral:{url:"https://api.mistral.ai/v1/chat/completions",kind:"openai"},openrouter:{url:"https://openrouter.ai/api/v1/chat/completions",kind:"openai"},custom:{url:"",kind:"openai"}};
function validAiConfig(b){const provider=String(b.provider||"").toLowerCase(),model=String(b.model||"").trim().slice(0,120),endpoint=String(b.endpoint||"").trim().slice(0,500);if(!aiProviders[provider]||!model)throw Error("Choisis un fournisseur et un modèle.");if(provider==="custom")throw Error("Les endpoints IA personnalisés sont temporairement désactivés pour prévenir les accès réseau non autorisés (SSRF). Utilise un fournisseur prédéfini.");return{provider,model,endpoint:provider==="custom"?endpoint:aiProviders[provider].url}}
async function invokeAi(cfg,key,messages){if(cfg.provider==="custom")throw Error("Les endpoints IA personnalisés sont désactivés pour prévenir les accès réseau non autorisés (SSRF).");const p=aiProviders[cfg.provider],signal=AbortSignal.timeout(45000);let url,headers,body;if(p.kind==="anthropic"){url=p.url;headers={"content-type":"application/json","x-api-key":key,"anthropic-version":"2023-06-01"};body={model:cfg.model,max_tokens:1100,system:messages[0].content,messages:messages.slice(1).map(x=>({role:x.role,content:x.content}))}}else if(p.kind==="gemini"){url=p.url+"/v1beta/models/"+encodeURIComponent(cfg.model)+":generateContent?key="+encodeURIComponent(key);headers={"content-type":"application/json"};body={systemInstruction:{parts:[{text:messages[0].content}]},contents:messages.slice(1).map(x=>({role:x.role==="assistant"?"model":"user",parts:[{text:x.content}]})),generationConfig:{maxOutputTokens:1100,temperature:.35}}}else{url=cfg.endpoint||p.url;headers={"content-type":"application/json",authorization:"Bearer "+key};body={model:cfg.model,messages,max_tokens:1100,temperature:.35}}const r=await fetch(url,{method:"POST",headers,body:JSON.stringify(body),signal,redirect:"error"}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(String(d.error?.message||d.message||"Erreur fournisseur HTTP "+r.status).slice(0,350));const answer=p.kind==="anthropic"?(d.content||[]).filter(x=>x.type==="text").map(x=>x.text).join("\n"):p.kind==="gemini"?(d.candidates?.[0]?.content?.parts||[]).map(x=>x.text||"").join("\n"):d.choices?.[0]?.message?.content;if(!answer)throw Error("Réponse IA vide.");return{answer:String(answer).slice(0,12000),usage:d.usage||d.usageMetadata||null}}
async function userAi(){
 const provider=String(process.env.BEP_AI_PROVIDER||"gemini").toLowerCase(),model=String(process.env.BEP_AI_MODEL||"gemini-2.5-flash"),key=String(process.env.BEP_AI_API_KEY||"").trim();
 if(!key||!aiProviders[provider])throw Error("Le Coach IA BEP intégré est indisponible. Le moteur local reste disponible.");
 return{cfg:{provider,model,endpoint:aiProviders[provider].url},key,mode:"bep"};
}
const BEP_AI_FREE_MONTHLY_LIMIT=Math.max(1,Math.min(500,Number(process.env.BEP_AI_FREE_MONTHLY_LIMIT)||60));
function aiMonthKey(){return new Date().toISOString().slice(0,7)}
async function consumeBepAiQuota(userId){
 const month=aiMonthKey();
 const r=await pool.query("INSERT INTO bep_ai_monthly_usage(user_id,month_key,used) VALUES($1,$2,1) ON CONFLICT(user_id,month_key) DO UPDATE SET used=bep_ai_monthly_usage.used+1,updated_at=NOW() WHERE bep_ai_monthly_usage.used < $3 RETURNING used",[userId,month,BEP_AI_FREE_MONTHLY_LIMIT]);
 if(!r.rowCount)throw Error("Tu as atteint ton quota gratuit du Coach IA pour ce mois. Il sera réinitialisé le mois prochain.");
 return{used:r.rows[0].used,limit:BEP_AI_FREE_MONTHLY_LIMIT,month};
}
async function releaseBepAiQuota(userId,month){await pool.query("UPDATE bep_ai_monthly_usage SET used=GREATEST(0,used-1),updated_at=NOW() WHERE user_id=$1 AND month_key=$2",[userId,month])}

