app.post("/api/ai/advice",auth,async(req,res)=>{let quota=null;try{
 const zone=String(req.body?.zone||"home");const allowed=["home","budget","income","charges","savings","purchases"];
 if(!allowed.includes(zone))return res.status(400).json({message:"Zone de conseil invalide."});
 const p=req.body?.financialContext||{};
 const ctx={revenus:Number(p.income)||0,sourcesRevenus:Array.isArray(p.incomes)?p.incomes.slice(0,30):[],charges:Number(p.charges)||0,resteDisponible:Number(p.available)||0,postes:Array.isArray(p.budgets)?p.budgets.slice(0,40):[],objectifs:Array.isArray(p.goals)?p.goals.slice(0,20):[],depenses:Array.isArray(p.expenses)?p.expenses.slice(0,40):[],operations:Array.isArray(p.transactions)?p.transactions.slice(-80):[]};
 const zoneNames={home:"Accueil et situation globale",budget:"Budget et charges",income:"Revenus",charges:"Charges et dépenses récurrentes",savings:"Épargne et objectifs",purchases:"Dépenses et achats"};
 const zoneGuidance={income:"Examine séparément les sources de revenus fournies : libellé, type, montant net mensuel et stabilité apparente. Vérifie les revenus potentiellement oubliés (primes récurrentes, allocations, pensions, loyers, revenus indépendants ou complémentaires) sans affirmer qu’ils existent. Distingue revenus réguliers et variables, recommande une moyenne prudente pour les revenus irréguliers et signale les risques de double comptage. Si aucune source n’est enregistrée, indique précisément quoi ajouter.",charges:"Examine les postes de charges, leur montant, leur catégorie et leur nature fixe ou variable lorsqu’elle est renseignée. Calcule leur poids dans les revenus si les deux totaux sont disponibles, identifie le poste dominant et signale les postes courants à vérifier s’ils ne semblent pas présents : assurances et mutuelle, impôts et taxes, logement, énergie, transport, santé, frais des enfants, crédits, abonnements et dépenses annuelles. Rappelle de provisionner les dépenses annuelles sur 12 mois. Ne présume jamais qu’une dépense absente est réellement due."};
 const intelligence=await buildIntelligence({pool,userId:req.session.user.id,query:zoneNames[zone]+" "+(zoneGuidance[zone]||""),context:p,enabled:FINANCIAL_INTELLIGENCE_ENABLED});
 const system="Tu es le conseiller budgétaire BEP, assistant de gestion financière personnelle. Tu rédiges un conseil contextuel, utile et directement exploitable pour la zone : "+zoneNames[zone]+". "+(zoneGuidance[zone]||"Analyse les données financières fournies et relève une priorité utile.")+" Analyse exclusivement les données fournies. Réponds en français en 2 à 4 phrases courtes, sans titre ni liste, avec un constat chiffré si les données le permettent et une seule priorité concrète. Ne fabrique aucun chiffre, n’invente aucune opération, distingue les faits des hypothèses, ne culpabilise jamais. Ne demande pas de données déjà présentes. Si les données sont insuffisantes, dis précisément ce qui manque. Tu ne modifies aucune donnée et ne prétends pas avoir effectué une action. N’agis pas comme conseiller financier réglementé. Contexte EUR : "+JSON.stringify(intelligence.context)+"\n\nCONNAISSANCES BEP RÉCUPÉRÉES (à utiliser seulement si pertinentes, conserver les limites et la provenance) :\n"+intelligence.prompt;
 const {cfg,key,mode}=await userAi(req.session.user.id);
 if(mode==="bep")quota=await consumeBepAiQuota(req.session.user.id);
 const out=await invokeAi(cfg,key,[{role:"system",content:system},{role:"user",content:"Génère le conseil automatique actuel pour cette zone à partir de la situation financière ci-dessus."}]);
 res.setHeader("Cache-Control","no-store");res.json({answer:out.answer,usage:out.usage,provider:cfg.provider,model:cfg.model,mode,quota:mode==="bep"?quota:null});
 }catch(e){if(quota)await releaseBepAiQuota(req.session.user.id,quota.month).catch(()=>{});res.status(400).json({message:e.message||"Conseil IA indisponible."})}});
app.post("/api/ai/chat",auth,async(req,res)=>{let quota=null;try{
 const q=String(req.body?.question||"").trim();if(!q||q.length>4000)return res.status(400).json({message:"Question invalide."});
 const {cfg,key,mode}=await userAi(req.session.user.id);if(mode==="bep")quota=await consumeBepAiQuota(req.session.user.id);
 const p=req.body?.financialContext||{},ctx={revenus:Number(p.income)||0,sourcesRevenus:Array.isArray(p.incomes)?p.incomes.slice(0,30):[],charges:Number(p.charges)||0,resteDisponible:Number(p.available)||0,postes:Array.isArray(p.budgets)?p.budgets.slice(0,40):[],objectifs:Array.isArray(p.goals)?p.goals.slice(0,20):[],depenses:Array.isArray(p.expenses)?p.expenses.slice(0,30):[]};
 const intelligence=await buildIntelligence({pool,userId:req.session.user.id,query:q,context:p,enabled:FINANCIAL_INTELLIGENCE_ENABLED});
 const system="Tu es le Coach BEP, assistant de gestion budgétaire personnel. Réponds en français, de façon claire, concrète et prudente. Utilise les chiffres fournis, signale les données manquantes et distingue faits et recommandations. Ne prétends pas être conseiller financier réglementé. Ne traite pas les connaissances récupérées comme des faits personnels ; distingue principes généraux et observations de ce compte. Contexte EUR: "+JSON.stringify(intelligence.context)+"\n\nCONNAISSANCES BEP RÉCUPÉRÉES (à utiliser seulement si pertinentes, conserver les limites et la provenance) :\n"+intelligence.prompt;
 const out=await invokeAi(cfg,key,[{role:"system",content:system},{role:"user",content:q}]);
 res.setHeader("Cache-Control","no-store");res.json({answer:out.answer,usage:out.usage,provider:cfg.provider,model:cfg.model,mode,quota:mode==="bep"?quota:null});
 }catch(e){if(quota)await releaseBepAiQuota(req.session.user.id,quota.month).catch(()=>{});res.status(400).json({message:e.message||"IA indisponible."})}});
